// The SAME GET /users/{id} route, four ways.

// Standard library (Go 1.22+): net/http types.
mux := http.NewServeMux()
mux.HandleFunc("GET /users/{id}", func(w http.ResponseWriter, r *http.Request) {
	fmt.Fprintf(w, "user %s", r.PathValue("id"))
})

// Chi: still net/http, thin router on top.
r := chi.NewRouter()
r.Get("/users/{id}", func(w http.ResponseWriter, req *http.Request) {
	fmt.Fprintf(w, "user %s", chi.URLParam(req, "id"))
})

// Gin: its own *gin.Context (net/http underneath).
g := gin.Default()
g.GET("/users/:id", func(c *gin.Context) {
	c.String(200, "user %s", c.Param("id"))
})

// Fiber: *fiber.Ctx, backed by fasthttp (NOT net/http).
app := fiber.New()
app.Get("/users/:id", func(c *fiber.Ctx) error {
	return c.SendString("user " + c.Params("id"))
})
